    {
        ["How to Play"] = "あそびかた", ["How to play Waiwai"] = "ワイワイのあそびかた",
        ["Favourites"] = "お気に入り", ["Favorites"] = "お気に入り",
        ["Original Songs"] = "オリジナル曲", ["Nijiiro"] = "ニジイロ", ["Custom tja"] = "カスタムTJA",
        ["Anime"] = "アニメ", ["Kids"] = "どうよう", ["Children and Folk"] = "どうよう",
        ["Variety"] = "バラエティ", ["Classical"] = "クラシック", ["Classical Music"] = "クラシック",
        ["Game Music"] = "ゲームミュージック", ["Namco Original"] = "ナムコオリジナル",
        ["Vocaloid"] = "ボーカロイド", ["Recommended"] = "おすすめ", ["Recently Played"] = "最近あそんだ曲",
        ["Dojo"] = "段位道場", ["Event"] = "イベント", ["Change Mode"] = "モード切替", ["Return"] = "もどる",
        ["To Normal"] = "通常モードへ", ["To Waiwai"] = "ワイワイへ",
    };

    private static readonly Dictionary<string, string> JapaneseBrowseOptions = new(StringComparer.Ordinal)
    {
        ["None"] = "なし", ["Title"] = "曲名", ["Artist"] = "アーティスト", ["Mapper"] = "譜面作者",
        ["Difficulty"] = "むずかしさ", ["Collections"] = "コレクション", ["Date Added"] = "追加日",
        ["BPM"] = "BPM", ["Length"] = "曲の長さ",
    };

    private static readonly Dictionary<string, string> JapaneseDescriptions = new(StringComparer.Ordinal)
    {
        ["Learn how to play the game!!"] = "太鼓のたたき方を覚えよう！！",
        ["Choose between the latest hits and the most popular songs!!"] = "新しい曲や人気の曲であそぼう！！",
        ["Play your favorite Anime songs!!"] = "大好きなアニメの曲であそぼう！！",
        ["Choose between exciting, upbeat and fun songs!!"] = "楽しくて元気になれる曲がいっぱい！！",
        ["Choose between various songs that everyone knows!!"] = "みんなが知っているいろんな曲であそぼう！！",
        ["Play famous Classical songs from the past!!"] = "有名なクラシックの曲であそぼう！！",
        ["Play the songs from your favorite games!!"] = "ゲームの曲であそぼう！！",
        ["Play the original songs from the Taiko series!!"] = "太鼓の達人のオリジナル曲であそぼう！！",
        ["Play songs that everyone likes!!"] = "みんなに人気の曲であそぼう！！",
        ["Play your favorite songs!!"] = "お気に入りの曲であそぼう！！",
        ["Choose between your recently played songs!!"] = "最近あそんだ曲を選ぼう！！",
        ["Complete objectives and test your skills!!"] = "お題に挑戦して腕前をためそう！！",
        ["Play your favorite Vocaloid songs!!"] = "ボーカロイドの曲であそぼう！！",
        ["Complete daily songs suited to your skill level!!"] = "自分に合った曲に毎日挑戦しよう！！",
        ["Practice for the Dan-i Dojo based on your skill level!!"] = "腕前に合わせて段位道場を練習しよう！！",
        ["Choose songs by difficulty and ★ ratings!!"] = "むずかしさや星の数で曲を選ぼう！！",
        ["Learn how to play Training Mode!!"] = "練習モードの使い方を覚えよう！！",
        ["Team up with a friend for high energy drumming!!"] = "友達といっしょに楽しくたたこう！！",
        ["Learn how to play Waiwai mode!!"] = "ワイワイのあそび方を覚えよう！！",
        ["Play the normal game with over 500 songs to choose from!!"] = "たくさんの曲がある通常モードであそぼう！！",
        ["Play the original songs!!"] = "オリジナルの\n曲で\nあそぼう！！",
        ["Play your osu!taiko maps!!"] = "osu!taikoの\n譜面で\nあそぼう！！",
        ["Play Taiko Nijiiro charts!!"] = "ニジイロの\n曲で\nあそぼう！！",
        ["Play your custom charts!!"] = "カスタムの\n譜面で\nあそぼう！！",
    };

    public static string Name(string text, bool english)
    {
        if (english) return text;
        if (JapaneseNames.TryGetValue(text, out var translated)) return translated;
        foreach (var (prefix, label) in new[] { ("Group: ", "グループ："), ("Sort: ", "並び順：") })
            if (text.StartsWith(prefix, StringComparison.Ordinal)
                && JapaneseBrowseOptions.TryGetValue(text[prefix.Length..], out var option))
                return label + option;
        return text;
    }
    public static string Description(string text, bool english)
    {
        var normalized = string.Join(' ', text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
        return english ? text : JapaneseDescriptions.GetValueOrDefault(normalized, text);
    }
    public static string FirstSongNotice(bool english) => english ? "Only available during the 1st song" : "1曲目のみ選べます";
}
